blocks.text:
*, *::before, *::after { box-sizing: border-box; }

/* border-box: width 300 = 테두리까지 합쳐 300
   content-box(기본): width 300 + padding + border 만큼 더 커진다 */

.row {
  display: flex;
  gap: 12px;          /* 자식 사이 간격 */
  align-items: center; /* 교차축 정렬 */
  flex-wrap: wrap;     /* 좁아지면 줄바꿈 */
}
.grow { flex: 1; }   /* 남는 자리를 먹는다 */

.cards {
  display: grid;
  /* 칸이 280px 아래로 안 내려가게, 남으면 자동으로 열을 늘린다 */
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

.card { position: relative; }        /* 기준점 */
.card .badge {
  position: absolute;                /* 기준점 안에서 */
  top: -8px; right: 12px;
}

.header { position: sticky; top: 0; }  /* 스크롤 따라붙기 */

:root { --accent: #a79bef; }
.btn { color: var(--accent); }

/* 어두운 화면에서만 값을 갈아 끼운다 */
@media (prefers-color-scheme: dark) {
  :root { --accent: #bdb4f4; }
}
